do $$ begin if not exists (select 1 from pg_enum where enumtypid = (select oid from pg_type where typname = 'app_permission' and nspname = 'rbac') and enumlabel = 'astro.read') then alter type rbac.app_permission add value 'astro.read'; alter type rbac.app_permission add value 'astro.create'; alter type rbac.app_permission add value 'qibla.read'; alter type rbac.app_permission add value 'qibla.create'; end if; end$$;
